WITH unpacked AS (SELECT id, service, level, latency_ms, SIZE(context) AS num_context, context['region'] AS region, COALESCE(context['trace'], 'direct') AS trace_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, COALESCE(context['region'], 'unknown') AS region_or_default FROM app_logs WHERE service = 'billing') SELECT CASE WHEN num_context >= 62 THEN 'LARGE' ELSE 'SMALL' END AS num_context_tier, ROUND(SUM(duration_sec) / NULLIF(COUNT(CASE WHEN level = 'INFO' THEN 1 END), 0), 2) AS duration_sec_per_info, STDDEV_SAMP(latency_ms) AS latency_ms_stddev, PERCENTILE_APPROX(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles, BIT_OR(latency_ms) AS latency_ms_bit_or FROM unpacked GROUP BY num_context_tier
